<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>Recibo de abono</title><style>@page{size:80mm auto;margin:0}*{box-sizing:border-box}body{width:80mm;margin:0;padding:4mm 3mm;font:11px/1.35 "Courier New",monospace;color:#000}.centrado{text-align:center}.tienda{font-size:16px;font-weight:bold}.linea{border-top:1px dashed #000;margin:8px 0}.fila{display:flex;justify-content:space-between;margin:5px 0}.monto{font-size:16px;font-weight:bold;border-top:1px solid #000;border-bottom:1px double #000;padding:6px 0}@media screen{body{margin:12px auto;box-shadow:0 0 0 1px #ddd}}</style></head><body><main><header class="centrado"><div class="tienda">Mi Abarrotería</div><div>RECIBO DE ABONO</div></header><div class="linea"></div><div class="fila"><span>Cliente</span><span><?php echo htmlspecialchars($abono['cliente_nombre']); ?></span></div><div class="fila"><span>Fecha</span><span><?php echo date('d/m/Y H:i',strtotime($abono['fecha'])); ?></span></div><div class="fila"><span>Forma de pago</span><span><?php echo htmlspecialchars($abono['forma_pago']); ?></span></div><div class="fila monto"><span>ABONO</span><span><?php echo formatearMoneda($abono['monto']); ?></span></div><p><?php echo htmlspecialchars($abono['observacion'] ?? ''); ?></p><p class="centrado">Gracias por su pago.</p></main><script>window.addEventListener('load',function(){window.print();});</script></body></html>